use super::*;
#[path="../../../🎟️work/🧪️tests/📥️bank/🦀️.rs"]mod funding;
use funding::{Bank,observe};
#[derive(Debug,PartialEq,semio_framework_value::NativeReceive,semio_framework_value::RetireOwned)]
struct Datum{label:String,values:Vec<u32>}
impl NativeIntrinsicRecord for Datum{const INTRINSIC_FIELD_ID:u16=1;}
fn bank()->Bank{let row:serde_json::Value=serde_json::from_str(semio_framework_test_fixtures::repo_text!("🧰️framework/🔨️modules/🗣️dsl/🧬️schema/🫴️receiving/📥️owned/🎟️work/📐️.json")).unwrap();Bank::new(&row["stock"])}
#[test]
fn native_intrinsic_record_receiving_preserves_original_custody_receipts_and_every_cancel_prefix(){let law:serde_json::Value=serde_json::from_str(semio_framework_test_fixtures::repo_text!("🧰️framework/🔨️modules/🗣️dsl/🧬️schema/🫴️receiving/📥️owned/🌳️intrinsic/🧪️tests/🔣️.json")).unwrap();let mut complete=0;for cut in std::iter::once(None).chain(law["cancelAt"].as_array().unwrap().iter().map(|v|Some(v.as_u64().unwrap()as usize))){let mut bank=bank();let value=DslValue::Object(vec![("label".into(),DslValue::String(law["document"]["label"].as_str().unwrap().into())),("values".into(),DslValue::Array(vec![DslValue::Number(semio_framework_value::Number::UInt(1)),DslValue::Number(semio_framework_value::Number::UInt(2)),DslValue::Number(semio_framework_value::Number::UInt(u32::MAX as u64))]))]);let mut source=Some(FieldValue::Record(RecordValue{fields:[(1,FieldValue::Value(value))].into_iter().collect()}));let(mut receiver,h)=observe(NativeIntrinsicReceiving::<Datum>::default);assert_eq!(h,(0,0));let mut callback=|_|true;let mut control=NativeDecodeControl::new(1<<24,&mut callback);let mut turns=0;while !receiver.is_ready()&&cut.is_none_or(|cut|turns<cut){let d=receiver.demands(&source,4096).unwrap();let g=bank.grant(4096);for grant in funding::denied(g,d){let(turn,h)=observe(||funding::receive(&mut control,grant,|native|receiver.step(&mut source,native,4096,grant)));assert_eq!(turn.work,0);assert_eq!(turn.result.unwrap(),Default::default());assert_eq!(h,(0,0));assert_eq!(receiver.demands(&source,4096).unwrap(),d);}let(turn,h)=observe(||funding::receive(&mut control,g,|native|receiver.step(&mut source,native,4096,g)));let p=turn.result.as_ref().copied().unwrap_or_else(|e|e.retained_progress());bank.post(g,p,turn.work,h);turn.result.unwrap();turns+=1;assert!(turns<10000);}if cut.is_none(){complete=turns;let mut output=None;let g=bank.grant(4096);let(turn,h)=observe(||receiver.take_into(&mut output,g));let p=turn.result.as_ref().copied().unwrap_or_else(|e|e.retained_progress());bank.post(g,p,turn.work,h);turn.result.unwrap();let output=output.unwrap();assert_eq!(output.label,law["document"]["label"].as_str().unwrap());assert_eq!(output.values,[1,2,u32::MAX]);assert_eq!(serde_json::json!({"label":output.label,"values":output.values}),law["document"]);funding::close(output,&mut bank);}for _ in 0..10000{if receiver.terminal_is_empty(){break}let d=receiver.close_demands(4096).unwrap();let g=bank.grant(4096);for grant in funding::denied(g,d){let(turn,h)=observe(||receiver.select_close(4096).unwrap().step(grant));assert_eq!(turn.work,0);assert_eq!(turn.result.unwrap().progress(),Default::default());assert_eq!(h,(0,0));assert_eq!(receiver.close_demands(4096).unwrap(),d);}let(turn,h)=observe(||receiver.select_close(4096).unwrap().step(g));let p=turn.result.as_ref().map(|s|s.progress()).unwrap_or_else(|e|e.retained_progress());bank.post(g,p,turn.work,h);turn.result.unwrap();}assert!(receiver.terminal_is_empty());assert_eq!(observe(||drop(receiver)).1,(0,0));if let Some(source)=source{funding::close(source,&mut bank);}}assert!(complete>0);}

#[test]fn selected_intrinsic_closure_requires_every_quoted_currency(){
 let law:serde_json::Value=serde_json::from_str(semio_framework_test_fixtures::repo_text!("🧰️framework/🔨️modules/🗣️dsl/🧬️schema/🫴️receiving/📥️owned/🌳️intrinsic/🧪️tests/🔣️.json")).unwrap();let demand=&law["selectedClosure"]["demand"];let n=|row:&serde_json::Value,key:&str|usize::try_from(row[key].as_u64().unwrap()).unwrap();let d=RetirementDemand{copy_bytes:n(demand,"copyBytes"),capacity_bytes:n(demand,"capacityBytes"),release_bytes:n(demand,"releaseBytes"),depth:n(demand,"depth")};for row in law["selectedClosure"]["cases"].as_array().unwrap(){let grant=&row["grant"];let g=RetainedCloneGrant{maximum_items:n(grant,"items"),maximum_copy_bytes:n(grant,"copyBytes"),maximum_capacity_bytes:n(grant,"capacityBytes"),maximum_release_bytes:n(grant,"releaseBytes"),maximum_depth:n(grant,"depth")};assert_eq!(funds(g,d),row["accepted"].as_bool().unwrap());}
}

#[derive(semio_framework_value::NativeReceive,semio_framework_value::RetireOwned)]struct QuotedDatum{label:semio_framework_value::shared_issuance::SealedShared<String>}
impl NativeIntrinsicRecord for QuotedDatum{const INTRINSIC_FIELD_ID:u16=1;}
struct RefusingPost{grant:RetainedCloneGrant,issued:bool,posted:bool,submitted:semio_framework_value::RetainedCloneProgress}
impl semio_framework_value_native_owned::NativeDecodeConstructionRecipient for RefusingPost{fn submitted(&self)->semio_framework_value::RetainedCloneProgress{self.submitted}fn grant(&mut self,d:RetirementDemand)->Result<RetainedCloneGrant,ValueError>{assert!(!self.issued);assert!(funds(self.grant,d));self.issued=true;Ok(self.grant)}fn accept(&mut self,g:RetainedCloneGrant,p:RetainedCloneProgress)->Result<(),ValueError>{self.submitted=self.submitted.checked_add(p)?;assert!(self.issued);assert!(p.fits(g)&&p.fits(self.grant));self.posted=true;Err(ValueError::literal(semio_framework_value::ValueRefusalKind::WorkLimit,"actual DSL caller refuses native receipt publication"))}}
#[test]fn actual_intrinsic_native_post_refusal_retains_full_cause_and_child_custody(){let mut bank=bank();let input=DslValue::Object(vec![("label".into(),DslValue::String("original quoted β".into()))]);let mut source=Some(FieldValue::Record(RecordValue{fields:[(1,FieldValue::Value(input))].into_iter().collect()}));let mut owner=NativeIntrinsicReceiving::<QuotedDatum>::default();let mut callback=|_|true;let mut native=NativeDecodeControl::new(1<<24,&mut callback);let mut failure=None;for _ in 0..10000{assert!(!owner.is_ready());let g=bank.grant(4096);let mut recipient=RefusingPost{grant:g,issued:false,posted:false,submitted:Default::default()};let mut actual_work=0;let(result,h)=observe(||native.with_construction_recipient(&mut recipient,|native|{let turn=owner.step(&mut source,native,4096,g);actual_work=turn.work;turn.result}));let p=result.as_ref().copied().unwrap_or_else(|e|e.retained_progress());bank.post(g,p,actual_work,h);match result{Ok(_)=>{},Err(error)=>{assert!(recipient.posted);assert!(error.quote_refusal.is_some());assert_eq!(error.quote_refusal.as_ref().unwrap().kind,semio_framework_value::ValueRefusalKind::WorkLimit);assert!(p.retained_capacity_bytes>0);assert_eq!(actual_work,1);failure=Some(error);break}}}assert!(failure.is_some());assert!(!owner.is_ready());assert!(!owner.terminal_is_empty());for _ in 0..10000{if owner.terminal_is_empty(){break}let g=bank.grant(4096);let(turn,h)=observe(||owner.close_step(g));let p=turn.result.as_ref().copied().unwrap_or_else(|e|e.retained_progress());bank.post(g,p,turn.work,h);turn.result.unwrap();}assert!(owner.terminal_is_empty());if let Some(source)=source{funding::close(source,&mut bank);}funding::close(failure.take().unwrap(),&mut bank);}
